import {test} from 'node:test';import assert from 'node:assert/strict';import {createLifeWorld,createIndividual,experience,successor,validateLifeWorld,STORY_LIMITS} from '../simulation/life-story.mjs';import {ensureOrganism,advanceOrganism} from '../ranch-story-adapter.mjs';
test('a successor has a new identity; predecessor remains addressable after save/restore',()=>{const w=createLifeWorld('a');const a=ensureOrganism(w,{slot:'pen-1',type:'goat',label:'Pip',born:0});const b=advanceOrganism(w,'pen-1',{year:16,span:14,type:'goat',label:'Fern'});assert.notEqual(a.id,b.id);assert.equal(a.lifecycle.status,'dead');assert.equal(b.origin.kind,'arrival');assert.deepEqual(b.origin.sources,[]);const restored=JSON.parse(JSON.stringify(w));assert.ok(validateLifeWorld(restored));assert.equal(restored.entities[b.id].origin.predecessor,a.id);});
test('propagation differs from construction and a whale requires no human rules',()=>{const w=createLifeWorld();const plant=createIndividual(w,{type:'flower',born:0});const seed=successor(w,'bed',plant.id,{at:1,type:'flower',originKind:'seed',sources:[plant.id]});const maker=createIndividual(w,{type:'robot'});const robot=createIndividual(w,{type:'robot',origin:{kind:'construction',sources:[maker.id]}});const whale=createIndividual(w,{type:'whale',capabilities:['migrate','kinship']});assert.equal(seed.origin.kind,'seed');assert.equal(robot.origin.kind,'construction');assert.ok(!w.definitions.whale.capabilities.includes('marriage'));assert.ok(validateLifeWorld(w));});
test('repeated events stay bounded while aggregate consequences survive',()=>{const w=createLifeWorld(),e=createIndividual(w,{type:'plant'});for(let i=0;i<10000;i++)experience(w,e.id,'flowering',i);assert.equal(e.events.length,STORY_LIMITS.individual);assert.equal(w.events.length,STORY_LIMITS.world);assert.equal(e.summary.flowering,10000);assert.ok(validateLifeWorld(w));});

test('700 plant generations retain bounded ancestors and explicit summarized origins',()=>{const w=createLifeWorld('plants');ensureOrganism(w,{slot:'flower',type:'flower',born:0,detail:'lineage'});for(let y=1;y<=700;y++)advanceOrganism(w,'flower',{year:y,span:1,type:'flower',label:'Flower',originKind:'seed',biological:true});const living=w.entities[w.occupants.flower];assert.equal(living.generation,701);assert.ok(Object.keys(w.entities).length<=129);assert.ok(w.compacted>500);assert.ok(validateLifeWorld(w));assert.ok(JSON.stringify(w).length<150000);assert.ok(Object.values(w.entities).some(e=>e.origin.summarizedSources?.length));});
import {inheritTraits} from '../simulation/life-traits.mjs';import {familyInterests,practice,chooseActivity} from '../simulation/life-learning.mjs';
test('simple heredity stays deterministic, bounded and accepts one parent',()=>{const schema={size:{default:1,min:.9,max:1.1,variation:.03}};const a=inheritTraits(schema,[{size:1.08}],'seed');assert.deepEqual(a,inheritTraits(schema,[{size:1.08}],'seed'));assert.ok(a.size<=1.1&&a.size>=.9);});
test('family influence and experience affect real choice without fixing an occupation',()=>{const a={id:'a',interests:{garden:.95,eggs:.1,groom:.1,apples:.1}},child={id:'c',interests:familyInterests([a],'c')};const before=child.interests.garden;practice(child,'garden');assert.ok(child.interests.garden>before);assert.equal(child.skills.garden,.025);assert.equal(child.occupation,undefined);let garden=0;for(let i=0;i<1000;i++)if(chooseActivity(a.interests,'task'+i)===0)garden++;assert.ok(garden>400);});

import {nominateHero} from '../simulation/life-story.mjs';
test('hero demotion and restore preserve salient memories within a fixed budget',()=>{const w=createLifeWorld(),e=createIndividual(w,{type:'goat'});nominateHero(w,e.id,true);for(let i=0;i<40;i++)experience(w,e.id,'encounter',i,{other:'visitor'+i,salience:5});assert.equal(e.memories.length,8);assert.equal(e.events.length,24);const before=structuredClone(e.memories);nominateHero(w,e.id,false);assert.deepEqual(e.memories,before);const restored=JSON.parse(JSON.stringify(w));assert.ok(validateLifeWorld(restored));assert.deepEqual(restored.entities[e.id].memories,before);});
test('story fidelity changes retention without altering lifecycle or biological traits',()=>{for(const mode of ['Low','Medium','High','Ultra']){const w=createLifeWorld();w.fidelity=mode;const e=createIndividual(w,{type:'horse',born:2,traits:{pace:1}});for(let i=0;i<100;i++)experience(w,e.id,'activity',i);assert.deepEqual(e.lifecycle,{born:2,status:'alive',ended:null});assert.deepEqual(e.traits,{pace:1});assert.ok(e.events.length<=24);assert.ok(validateLifeWorld(w));}});
